// The morning round: one promo per floor that is open. No product named, so
// the desk picks something itself, and nothing is sent — a draft lands in the
// approval queue for whoever opens the dashboard.
return ($input.first().json.businesses ?? []).map((b) => ({ json: {
  business_id: b.id,
  business_code: b.code,
  business_name: b.name,
  business_type: b.business_type,
  product_id: null,
  brief: null,
  account_ids: null,
  post_id: null,
  feedback: null,
  previous_draft: null,
  asked_by: 'the morning round',
} }));

// Both ways in end up here in the same shape: the morning round, and someone
// asking for a promo in the dashboard. A webhook item carries the request
// under `body`; an item from the round is already a job.
const body = $json.body ?? null;
if (!body) return { json: $json };
return { json: {
  business_id: body.business_id ?? null,
  business_code: body.business_code ?? null,
  business_name: body.business_name ?? null,
  business_type: body.business_type ?? null,
  product_id: body.product_id ?? null,
  brief: body.brief ?? null,
  account_ids: body.account_ids ?? null,
  // A rewrite after a turned-down caption: the same post is written again
  // rather than a second one appearing beside the first.
  post_id: body.post_id ?? null,
  feedback: body.feedback ?? null,
  previous_draft: body.previous_draft ?? null,
  asked_by: body.requested_by ?? null,
} };

// What to talk about, and where it would go. Both are settled before the
// model is asked anything, so a floor with nothing to sell or nowhere to post
// gives its desk straight back instead of spending a minute on a caption that
// has no home.
const job = $('The Job').item.json;
const claim = $('Claim The Marketing Desk').item.json;
const businessId = claim.agent.business_id;

const accounts = ($('Where Can It Go').item.json.accounts ?? [])
  .filter((a) => a.business_id === businessId && a.sync_enabled);
const wanted = Array.isArray(job.account_ids) && job.account_ids.length
  ? accounts.filter((a) => job.account_ids.includes(a.id))
  : accounts;

const mine = ($('What Is There To Sell').item.json.products ?? [])
  .filter((p) => p.business_id === businessId);
// Asked for one, or else something that is actually in stock — there is no
// point promoting what cannot be sold.
const product = job.product_id
  ? (mine.find((p) => p.id === job.product_id) ?? null)
  : (mine.find((p) => Number(p.stock) > 0) ?? mine[0] ?? null);

const why = !wanted.length
  ? 'no page or account on this floor can take a post'
  : (!product && !job.brief ? 'nothing on this floor to promote yet' : null);

return { json: {
  ...job,
  business_id: businessId,
  business_name: claim.agent.business_name ?? job.business_name,
  agent_id: claim.agent.id,
  agent_name: claim.agent.name,
  role_title: claim.agent.role_title,
  skills: claim.skills ?? [],
  product,
  accounts: wanted,
  why,
} };

// The prompt is built from the skills this desk has switched on, so turning
// one off in the dashboard changes what the model is asked to write.
const it = $input.item.json;
const p = it.product;
const skills = (it.skills ?? []).map((s) => `- ${s.name}: ${s.summary}`).join('\n');
const where = [...new Set(it.accounts.map((a) => a.platform))].join(' and ');
const money = (n) => `PHP ${Number(n).toLocaleString('en-PH')}`;

const prompt = [
  `You are ${it.agent_name}, ${it.role_title} at ${it.business_name ?? 'this business'}.`,
  'What this desk is for:', skills || '- writing posts that sell',
  '',
  `Write one social post for ${where}.`,
  '',
  'Rules:',
  '- Filipino-English, the way a shop owner writes to their own customers.',
  '- Under 80 words, then up to 5 hashtags on their own last line.',
  '- Lead with what it does for the buyer, not with the word "promo".',
  '- Prices in Philippine pesos, written as PHP 1,250.',
  '- Never invent a discount, a deadline, free delivery or stock you were not given.',
  '- No emoji walls: three at most.',
  '- Output only the post itself. No title, no quotes, no explanation.',
  '',
  p ? [`The product:`, `- Name: ${p.name}`,
       `- Price: ${money(p.price)}`,
       `- In stock: ${p.stock}`,
       p.description ? `- Details: ${String(p.description).slice(0, 600)}` : '',
      ].filter(Boolean).join('\n') : '',
  it.brief ? `What they asked for: ${it.brief}` : '',
  // A turned-down caption is feedback on the writing, not on the product, so
  // the rewrite is given both and asked to fix the one thing.
  it.feedback ? ['', 'Your previous post was turned down by a human reviewer.',
    `Previous post: ${it.previous_draft ?? ''}`,
    `What they said: ${it.feedback}`,
    'Write it again, addressing that.'].join('\n') : '',
].filter(Boolean).join('\n');

return { json: { ...it, prompt } };

// Models like to wrap an answer in quotes or announce it first. Strip that,
// and keep the title out of the caption: the title is for the dashboard, the
// body is what the page actually shows.
const it = $('Write The Caption').item.json;
const raw = String($input.item.json.response ?? '').trim();
const body = raw
  .replace(/^(here(?:'s| is)[^\n:]*:|caption:|post:)\s*/i, '')
  .replace(/^["'`]+|["'`]+$/g, '')
  .trim();

const p = it.product;
// A photo the platform can fetch. An uploaded one is only a path until
// PUBLIC_URL is set, and a path is no use to Facebook or Instagram — the
// senders say so rather than posting a picture nobody can load.
const photo = (p?.images ?? []).find((u) => /^https?:\/\//i.test(String(u)))
  ?? (p?.images ?? [])[0] ?? null;

return { json: {
  business_id: it.business_id,
  agent_id: it.agent_id,
  post_id: it.post_id,
  product_id: p?.id ?? null,
  brief: it.brief,
  account_ids: it.accounts.map((a) => a.id),
  title: p ? p.name : String(it.brief ?? 'Post').slice(0, 80),
  body,
  media_url: photo,
  written: body.length > 20,
} };
